# ! [doc = " Ways to create a `str` from bytes slice."] use split_decls_genesis :: ourprelude :: * ; use super :: Utf8Error ; use super :: validations :: run_utf8_validation ; use crate :: { mem , ptr } ; #[doc = " Converts a slice of bytes to a string slice."] #[doc = ""] #[doc = " This is an alias to [`str::from_utf8`]."] #[doc = ""] #[doc = " A string slice ([`&str`]) is made of bytes ([`u8`]), and a byte slice"] #[doc = " ([`&[u8]`][byteslice]) is made of bytes, so this function converts between"] #[doc = " the two. Not all byte slices are valid string slices, however: [`&str`] requires"] #[doc = " that it is valid UTF-8. `from_utf8()` checks to ensure that the bytes are valid"] #[doc = " UTF-8, and then does the conversion."] #[doc = ""] #[doc = " [`&str`]: str"] #[doc = " [byteslice]: slice"] #[doc = ""] #[doc = " If you are sure that the byte slice is valid UTF-8, and you don't want to"] #[doc = " incur the overhead of the validity check, there is an unsafe version of"] #[doc = " this function, [`from_utf8_unchecked`], which has the same"] #[doc = " behavior but skips the check."] #[doc = ""] #[doc = " If you need a `String` instead of a `&str`, consider"] #[doc = " [`String::from_utf8`][string]."] #[doc = ""] #[doc = " [string]: ../../std/string/struct.String.html#method.from_utf8"] #[doc = ""] #[doc = " Because you can stack-allocate a `[u8; N]`, and you can take a"] #[doc = " [`&[u8]`][byteslice] of it, this function is one way to have a"] #[doc = " stack-allocated string. There is an example of this in the"] #[doc = " examples section below."] #[doc = ""] #[doc = " [byteslice]: slice"] #[doc = ""] #[doc = " # Errors"] #[doc = ""] #[doc = " Returns `Err` if the slice is not UTF-8 with a description as to why the"] #[doc = " provided slice is not UTF-8."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " // some bytes, in a vector"] #[doc = " let sparkle_heart = vec![240, 159, 146, 150];"] #[doc = ""] #[doc = " // We can use the ? (try) operator to check if the bytes are valid"] #[doc = " let sparkle_heart = str::from_utf8(&sparkle_heart)?;"] #[doc = ""] #[doc = " assert_eq!(\"💖\", sparkle_heart);"] #[doc = " # Ok::<_, str::Utf8Error>(())"] #[doc = " ```"] #[doc = ""] #[doc = " Incorrect bytes:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " // some invalid bytes, in a vector"] #[doc = " let sparkle_heart = vec![0, 159, 146, 150];"] #[doc = ""] #[doc = " assert!(str::from_utf8(&sparkle_heart).is_err());"] #[doc = " ```"] #[doc = ""] #[doc = " See the docs for [`Utf8Error`] for more details on the kinds of"] #[doc = " errors that can be returned."] #[doc = ""] #[doc = " A \"stack allocated string\":"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " // some bytes, in a stack-allocated array"] #[doc = " let sparkle_heart = [240, 159, 146, 150];"] #[doc = ""] #[doc = " // We know these bytes are valid, so just use `unwrap()`."] #[doc = " let sparkle_heart: &str = str::from_utf8(&sparkle_heart).unwrap();"] #[doc = ""] #[doc = " assert_eq!(\"💖\", sparkle_heart);"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] #[rustc_const_stable (feature = "const_str_from_utf8_shared" , since = "1.63.0")] #[rustc_diagnostic_item = "str_from_utf8"] pub const fn from_utf8 (v : & [u8]) -> Result < & str , Utf8Error > { match run_utf8_validation (v) { Ok (_) => { Ok (unsafe { from_utf8_unchecked (v) }) } Err (err) => Err (err) , } } #[doc = " Converts a mutable slice of bytes to a mutable string slice."] #[doc = ""] #[doc = " This is an alias to [`str::from_utf8_mut`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " // \"Hello, Rust!\" as a mutable vector"] #[doc = " let mut hellorust = vec![72, 101, 108, 108, 111, 44, 32, 82, 117, 115, 116, 33];"] #[doc = ""] #[doc = " // As we know these bytes are valid, we can use `unwrap()`"] #[doc = " let outstr = str::from_utf8_mut(&mut hellorust).unwrap();"] #[doc = ""] #[doc = " assert_eq!(\"Hello, Rust!\", outstr);"] #[doc = " ```"] #[doc = ""] #[doc = " Incorrect bytes:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " // Some invalid bytes in a mutable vector"] #[doc = " let mut invalid = vec![128, 223];"] #[doc = ""] #[doc = " assert!(str::from_utf8_mut(&mut invalid).is_err());"] #[doc = " ```"] #[doc = " See the docs for [`Utf8Error`] for more details on the kinds of"] #[doc = " errors that can be returned."] #[stable (feature = "str_mut_extras" , since = "1.20.0")] #[rustc_const_stable (feature = "const_str_from_utf8" , since = "1.87.0")] #[rustc_diagnostic_item = "str_from_utf8_mut"] pub const fn from_utf8_mut (v : & mut [u8]) -> Result < & mut str , Utf8Error > { match run_utf8_validation (v) { Ok (_) => { Ok (unsafe { from_utf8_unchecked_mut (v) }) } Err (err) => Err (err) , } } #[doc = " Converts a slice of bytes to a string slice without checking"] #[doc = " that the string contains valid UTF-8."] #[doc = ""] #[doc = " This is an alias to [`str::from_utf8_unchecked`]."] #[doc = ""] #[doc = " See the safe version, [`from_utf8`], for more information."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " The bytes passed in must be valid UTF-8."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " // some bytes, in a vector"] #[doc = " let sparkle_heart = vec![240, 159, 146, 150];"] #[doc = ""] #[doc = " let sparkle_heart = unsafe {"] #[doc = "     str::from_utf8_unchecked(&sparkle_heart)"] #[doc = " };"] #[doc = ""] #[doc = " assert_eq!(\"💖\", sparkle_heart);"] #[doc = " ```"] #[inline] #[must_use] #[stable (feature = "rust1" , since = "1.0.0")] #[rustc_const_stable (feature = "const_str_from_utf8_unchecked" , since = "1.55.0")] #[rustc_diagnostic_item = "str_from_utf8_unchecked"] pub const unsafe fn from_utf8_unchecked (v : & [u8]) -> & str { unsafe { mem :: transmute (v) } } #[doc = " Converts a slice of bytes to a string slice without checking"] #[doc = " that the string contains valid UTF-8; mutable version."] #[doc = ""] #[doc = " This is an alias to [`str::from_utf8_unchecked_mut`]."] #[doc = ""] #[doc = " See the immutable version, [`from_utf8_unchecked()`] for documentation and safety requirements."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " use std::str;"] #[doc = ""] #[doc = " let mut heart = vec![240, 159, 146, 150];"] #[doc = " let heart = unsafe { str::from_utf8_unchecked_mut(&mut heart) };"] #[doc = ""] #[doc = " assert_eq!(\"💖\", heart);"] #[doc = " ```"] #[inline] #[must_use] #[stable (feature = "str_mut_extras" , since = "1.20.0")] #[rustc_const_stable (feature = "const_str_from_utf8_unchecked_mut" , since = "1.83.0")] #[rustc_diagnostic_item = "str_from_utf8_unchecked_mut"] pub const unsafe fn from_utf8_unchecked_mut (v : & mut [u8]) -> & mut str { unsafe { & mut * (v as * mut [u8] as * mut str) } } #[doc = " Creates a `&str` from a pointer and a length."] #[doc = ""] #[doc = " The pointed-to bytes must be valid UTF-8."] #[doc = " If this might not be the case, use `str::from_utf8(slice::from_raw_parts(ptr, len))`,"] #[doc = " which will return an `Err` if the data isn't valid UTF-8."] #[doc = ""] #[doc = " This function is the `str` equivalent of [`slice::from_raw_parts`](crate::slice::from_raw_parts)."] #[doc = " See that function's documentation for safety concerns and examples."] #[doc = ""] #[doc = " The mutable version of this function is [`from_raw_parts_mut`]."] #[inline] #[must_use] #[unstable (feature = "str_from_raw_parts" , issue = "119206")] pub const unsafe fn from_raw_parts < 'a > (ptr : * const u8 , len : usize) -> & 'a str { unsafe { & * ptr :: from_raw_parts (ptr , len) } } #[doc = " Creates a `&mut str` from a pointer and a length."] #[doc = ""] #[doc = " The pointed-to bytes must be valid UTF-8."] #[doc = " If this might not be the case, use `str::from_utf8_mut(slice::from_raw_parts_mut(ptr, len))`,"] #[doc = " which will return an `Err` if the data isn't valid UTF-8."] #[doc = ""] #[doc = " This function is the `str` equivalent of [`slice::from_raw_parts_mut`](crate::slice::from_raw_parts_mut)."] #[doc = " See that function's documentation for safety concerns and examples."] #[doc = ""] #[doc = " The immutable version of this function is [`from_raw_parts`]."] #[inline] #[must_use] #[unstable (feature = "str_from_raw_parts" , issue = "119206")] pub const unsafe fn from_raw_parts_mut < 'a > (ptr : * mut u8 , len : usize) -> & 'a mut str { unsafe { & mut * ptr :: from_raw_parts_mut (ptr , len) } }